from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

def solve():
    V = 19
    E_target = 27

    solver = Glucose4()

    def var(i, j):
        if i > j: i, j = j, i
        return i * V + j + 1

    edge_vars = [var(i, j) for i in range(V) for j in range(i+1, V)]

    # At least E_target edges
    cnf = CardEnc.atleast(lits=edge_vars, bound=E_target, encoding=EncType.seqcounter)
    for clause in cnf.clauses:
        solver.add_clause(clause)

    # CEGAR loop
    iteration = 0
    while True:
        iteration += 1
        res = solver.solve()
        if not res:
            print("UNSAT")
            break

        model = solver.get_model()
        edges = [(i, j) for i in range(V) for j in range(i+1, V) if model[var(i, j)-1] > 0]

        # Build adjacency list
        adj = {i: [] for i in range(V)}
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Function to find all cycles up to length 7
        def find_short_cycles(adj, max_len=7):
            cycles = []
            for n in range(V):
                queue = [(n, [n])]
                while queue:
                    curr, path = queue.pop(0)
                    if len(path) > max_len:
                        continue
                    for neighbor in adj[curr]:
                        if neighbor == path[0] and len(path) >= 3:
                            cycle = path[:]
                            min_idx = cycle.index(min(cycle))
                            if cycle[(min_idx+1)%len(cycle)] > cycle[(min_idx-1)%len(cycle)]:
                                cycle = cycle[min_idx:] + cycle[:min_idx]
                            else:
                                cycle = cycle[min_idx::-1] + cycle[:min_idx:-1]
                            if cycle not in cycles:
                                cycles.append(cycle)
                        elif neighbor not in path:
                            queue.append((neighbor, path + [neighbor]))
            return cycles

        cycles = find_short_cycles(adj, 7)
        if not cycles:
            print("SAT! Girth >= 8")
            print(edges)
            break

        # Add clauses to forbid these cycles
        for cycle in cycles:
            clause = []
            for k in range(len(cycle)):
                u, v = cycle[k], cycle[(k+1)%len(cycle)]
                clause.append(-var(u, v))
            solver.add_clause(clause)

        if iteration % 100 == 0:
            print(f"Iteration {iteration}, added {len(cycles)} cycle clauses. Edges in current model: {len(edges)}")

solve()

